name: Nustrim TV V2.1C Full Player Control Bar P1

on:
  workflow_dispatch:

permissions:
  contents: write
  actions: write

concurrency:
  group: nustrim-tv-v2-1c-full-player-controlbar-p1
  cancel-in-progress: false

env:
  TARGET_VERSION: "0.27.2-tv-v2.1c-controlbar"
  LIVE_V21B_PLAYER_SHA: "927ef644b9eaa5234c49d2049201e3362032edb94cfcff1b5731b5704e2323a1"

jobs:
  v21c:
    runs-on: ubuntu-latest
    timeout-minutes: 120

    steps:
      - name: Checkout exact main
        uses: actions/checkout@v7
        with:
          ref: main
          fetch-depth: 0

      - name: Sync origin main
        shell: bash
        run: |
          set -euo pipefail
          git fetch --no-tags origin main
          git checkout -B main origin/main
          git reset --hard origin/main

      - name: Set up Java
        uses: actions/setup-java@v5
        with:
          distribution: temurin
          java-version: "17"

      - name: Set up Gradle
        uses: gradle/actions/setup-gradle@v6
        with:
          gradle-version: "9.5.0"

      - name: Exact V2.1-B player preflight
        shell: bash
        run: |
          set -euo pipefail

          DIR="$RUNNER_TEMP/tv-v21c"
          mkdir -p "$DIR"

          PLAYER="app/src/main/java/app/nudroidlabs/nustrim/tv/player/TvPlayerScreen.kt"
          DETAILS="app/src/main/java/app/nudroidlabs/nustrim/tv/details/TvDetailsScreen.kt"

          test -f "$PLAYER"
          test -f "$DETAILS"
          test -f app/src/main/java/app/nudroidlabs/nustrim/core/source/StreamSourceAggregator.kt
          test -f app/src/main/java/app/nudroidlabs/nustrim/core/source/SubtitleSourceAggregator.kt
          test -f app/src/main/java/app/nudroidlabs/nustrim/core/source/InstalledSourceStore.kt
          test -f app/src/main/java/app/nudroidlabs/nustrim/ui/UiPreferences.kt
          test -f .github/workflows/build.yml
          test -d app/src/main/java/app/nudroidlabs/nustrim/core/update

          grep -q 'versionName = "0.27.1-tv-v2.1b-autonext"' app/build.gradle.kts

          actual_sha="$(sha256sum "$PLAYER" | awk '{print $1}')"
          if [[ "$actual_sha" != "$LIVE_V21B_PLAYER_SHA" ]]; then
            echo "::error::TvPlayerScreen changed since the green V2.1-B baseline."
            echo "expected=$LIVE_V21B_PLAYER_SHA"
            echo "actual=$actual_sha"
            exit 1
          fi

          grep -q 'previousEpisodeTitle: String?' "$PLAYER"
          grep -q 'nextEpisodeTitle: String?' "$PLAYER"
          grep -q 'onPreviousEpisode: (() -> Unit)?' "$PLAYER"
          grep -q 'onNextEpisode: (() -> Unit)?' "$PLAYER"
          grep -q 'autoNextCountdown' "$PLAYER"
          grep -q 'Key.MediaPrevious' "$PLAYER"
          grep -q 'Key.MediaNext' "$PLAYER"
          grep -q 'TvPlayerTrackPanel.AUDIO' "$PLAYER"
          grep -q 'TvPlayerTrackPanel.SUBTITLES' "$PLAYER"
          grep -q 'setSubtitleConfigurations(subtitleConfigurations)' "$PLAYER"

          cp "$DETAILS" "$DIR/Details.before.kt"
          cp app/src/main/java/app/nudroidlabs/nustrim/tv/home/TvHomeScreen.kt "$DIR/Home.before.kt"
          cp app/src/main/java/app/nudroidlabs/nustrim/tv/search/TvSearchScreen.kt "$DIR/Search.before.kt"
          cp app/src/main/java/app/nudroidlabs/nustrim/tv/library/TvLibraryScreen.kt "$DIR/Library.before.kt"
          cp app/src/main/java/app/nudroidlabs/nustrim/tv/settings/TvSettingsScreen.kt "$DIR/Settings.before.kt"
          cp app/src/main/java/app/nudroidlabs/nustrim/core/source/StreamSourceAggregator.kt "$DIR/StreamAggregator.before.kt"
          cp app/src/main/java/app/nudroidlabs/nustrim/core/source/SubtitleSourceAggregator.kt "$DIR/SubtitleAggregator.before.kt"
          cp app/src/main/java/app/nudroidlabs/nustrim/core/source/InstalledSourceStore.kt "$DIR/InstalledSourceStore.before.kt"
          cp app/src/main/java/app/nudroidlabs/nustrim/ui/UiPreferences.kt "$DIR/UiPreferences.before.kt"
          cp app/src/main/java/app/nudroidlabs/nustrim/ui/NustrimApp.kt "$DIR/NustrimApp.before.kt"

          sha256sum .github/workflows/build.yml > "$DIR/build.before"
          find app/src/main/java/app/nudroidlabs/nustrim/core/update             -type f -print0 | sort -z | xargs -0 sha256sum             > "$DIR/updater.before"

          {
            echo "NUSTRIM TV V2.1-C FULL PLAYER CONTROL BAR P1"
            echo "============================================"
            echo "sha=$(git rev-parse HEAD)"
            echo "player_sha=$actual_sha"
            grep -m1 'versionCode' app/build.gradle.kts
            grep -m1 'versionName' app/build.gradle.kts
          } | tee "$DIR/preflight.txt"

      - name: Write full player control bar
        shell: bash
        run: |
          set -euo pipefail
          python3 - <<'PY'
          from pathlib import Path
          import base64
          
          path = Path(
              "app/src/main/java/app/nudroidlabs/nustrim/tv/player/TvPlayerScreen.kt"
          )
          path.write_bytes(base64.b64decode(""))
          print("WRITE:", path)
          PY

      - name: Set V2.1-C version
        shell: bash
        run: |
          set -euo pipefail
          python3 - <<'PY'
          from pathlib import Path
          import os
          import re
          
          path = Path("app/build.gradle.kts")
          text = path.read_text(encoding="utf-8")
          target = os.environ["TARGET_VERSION"]
          
          cm = re.search(r'versionCode\s*=\s*(\d+)', text)
          nm = re.search(r'versionName\s*=\s*"([^"]+)"', text)
          if not cm or not nm:
              raise SystemExit("Could not parse app version.")
          
          old_code = int(cm.group(1))
          old_name = nm.group(1)
          new_code = old_code if old_name == target else old_code + 1
          
          text = re.sub(
              r'versionCode\s*=\s*\d+',
              f'versionCode = {new_code}',
              text,
              count=1,
          )
          text = re.sub(
              r'versionName\s*=\s*"[^"]+"',
              f'versionName = "{target}"',
              text,
              count=1,
          )
          
          path.write_text(text, encoding="utf-8")
          print(f"versionName: {old_name} -> {target}")
          print(f"versionCode: {old_code} -> {new_code}")
          PY

      - name: V2.1-C architecture audit
        shell: bash
        run: |
          set -euo pipefail

          DIR="$RUNNER_TEMP/tv-v21c"
          PLAYER="app/src/main/java/app/nudroidlabs/nustrim/tv/player/TvPlayerScreen.kt"

          echo "AUDIT VERSION: TV-V2.1C-FULL-CONTROL-BAR-P1"

          grep -q 'private fun TvPlayerControlButton(' "$PLAYER"
          grep -q 'id = "previous"' "$PLAYER"
          grep -q 'id = "rewind"' "$PLAYER"
          grep -q 'id = "play"' "$PLAYER"
          grep -q 'id = "forward"' "$PLAYER"
          grep -q 'id = "next"' "$PLAYER"
          grep -q 'id = "audio"' "$PLAYER"
          grep -q 'id = "subtitles"' "$PLAYER"
          grep -q 'id = "sources"' "$PLAYER"

          grep -q 'playControlRequester.requestFocus()' "$PLAYER"
          grep -q 'audioControlRequester.requestFocus()' "$PLAYER"
          grep -q 'subtitleControlRequester.requestFocus()' "$PLAYER"
          grep -q 'focusedControlId == null' "$PLAYER"
          grep -q 'requestControlFocus()' "$PLAYER"

          # V2.1-A and V2.1-B behavior stays intact.
          grep -q 'autoNextCountdown' "$PLAYER"
          grep -q 'Key.MediaPrevious' "$PLAYER"
          grep -q 'Key.MediaNext' "$PLAYER"
          grep -q 'setSubtitleConfigurations(subtitleConfigurations)' "$PLAYER"
          grep -q 'setPreferredTextLanguages' "$PLAYER"
          grep -q 'setDefaultRequestProperties(stream.headers)' "$PLAYER"

          # Protect everything outside the Player.
          cmp "$DIR/Details.before.kt" app/src/main/java/app/nudroidlabs/nustrim/tv/details/TvDetailsScreen.kt
          cmp "$DIR/Home.before.kt" app/src/main/java/app/nudroidlabs/nustrim/tv/home/TvHomeScreen.kt
          cmp "$DIR/Search.before.kt" app/src/main/java/app/nudroidlabs/nustrim/tv/search/TvSearchScreen.kt
          cmp "$DIR/Library.before.kt" app/src/main/java/app/nudroidlabs/nustrim/tv/library/TvLibraryScreen.kt
          cmp "$DIR/Settings.before.kt" app/src/main/java/app/nudroidlabs/nustrim/tv/settings/TvSettingsScreen.kt
          cmp "$DIR/StreamAggregator.before.kt" app/src/main/java/app/nudroidlabs/nustrim/core/source/StreamSourceAggregator.kt
          cmp "$DIR/SubtitleAggregator.before.kt" app/src/main/java/app/nudroidlabs/nustrim/core/source/SubtitleSourceAggregator.kt
          cmp "$DIR/InstalledSourceStore.before.kt" app/src/main/java/app/nudroidlabs/nustrim/core/source/InstalledSourceStore.kt
          cmp "$DIR/UiPreferences.before.kt" app/src/main/java/app/nudroidlabs/nustrim/ui/UiPreferences.kt
          cmp "$DIR/NustrimApp.before.kt" app/src/main/java/app/nudroidlabs/nustrim/ui/NustrimApp.kt

          sha256sum .github/workflows/build.yml > "$DIR/build.after"
          find app/src/main/java/app/nudroidlabs/nustrim/core/update             -type f -print0 | sort -z | xargs -0 sha256sum             > "$DIR/updater.after"
          cmp "$DIR/build.before" "$DIR/build.after"
          cmp "$DIR/updater.before" "$DIR/updater.after"

          grep -q 'versionName = "0.27.2-tv-v2.1c-controlbar"' app/build.gradle.kts
          grep -q 'minSdk = 23' app/build.gradle.kts

          git diff --check
          git diff --name-status | tee "$DIR/changed-files.txt"

          unexpected="$(
            git diff --name-only |
            grep -v -E               '^(app/build.gradle.kts|app/src/main/java/app/nudroidlabs/nustrim/tv/player/TvPlayerScreen.kt)$'               || true
          )"
          if [[ -n "$unexpected" ]]; then
            echo "::error::Unexpected files changed:"
            printf '%s\n' "$unexpected"
            exit 1
          fi

          git diff > "$DIR/v21c.patch"

          echo "PASS: focusable full player control bar"
          echo "PASS: Previous / -10 / Play-Pause / +10 / Next"
          echo "PASS: Audio / Subtitles / Sources"
          echo "PASS: Down enters bar at Play-Pause"
          echo "PASS: Up exits bar back to video"
          echo "PASS: focused bar stays visible"
          echo "PASS: Audio/Subtitle picker returns to originating button"
          echo "PASS: V2.1-A tracks + V2.1-B auto-next retained"
          echo "PASS: Details/Sources/Mobile/updater/signing protected"

      - name: Compile debug
        shell: bash
        run: |
          set -euo pipefail
          gradle --no-daemon --build-cache             :app:compileDebugKotlin             --stacktrace             --console=plain             2>&1 | tee "$RUNNER_TEMP/tv-v21c/compile.log"

      - name: Unit regression tests
        shell: bash
        run: |
          set -euo pipefail
          gradle --no-daemon --build-cache             :app:testDebugUnitTest             --stacktrace             --console=plain             2>&1 | tee "$RUNNER_TEMP/tv-v21c/tests.log"

      - name: Release lint
        shell: bash
        run: |
          set -euo pipefail
          gradle --no-daemon --build-cache             :app:lintRelease             --stacktrace             --console=plain             2>&1 | tee "$RUNNER_TEMP/tv-v21c/lint-release.log"

      - name: Assemble debug
        shell: bash
        run: |
          set -euo pipefail
          gradle --no-daemon --build-cache             :app:assembleDebug             --stacktrace             --console=plain             2>&1 | tee "$RUNNER_TEMP/tv-v21c/assemble.log"

      - name: Commit and push V2.1-C
        shell: bash
        run: |
          set -euo pipefail
          exec > >(tee "$RUNNER_TEMP/tv-v21c/push.log") 2>&1

          git config user.name "github-actions[bot]"
          git config user.email "41898282+github-actions[bot]@users.noreply.github.com"

          git add             app/src/main/java/app/nudroidlabs/nustrim/tv/player/TvPlayerScreen.kt             app/build.gradle.kts

          git diff --cached --check

          if ! git diff --cached --quiet; then
            git commit -m "feat(tv): add full player control bar"
            git fetch --no-tags origin main
            git rebase origin/main
            git push origin HEAD:main
          fi

      - name: Verify actual origin main
        shell: bash
        run: |
          set -euo pipefail
          git fetch --no-tags origin main
          echo "origin_main_sha=$(git rev-parse origin/main)"             | tee "$RUNNER_TEMP/tv-v21c/remote-main.txt"

          python3 - <<'PY'
          import subprocess
          
          target = "0.27.2-tv-v2.1c-controlbar"
          
          player = subprocess.check_output(
              [
                  "git", "show",
                  "origin/main:app/src/main/java/app/nudroidlabs/nustrim/tv/player/TvPlayerScreen.kt",
              ],
              text=True,
          )
          details = subprocess.check_output(
              [
                  "git", "show",
                  "origin/main:app/src/main/java/app/nudroidlabs/nustrim/tv/details/TvDetailsScreen.kt",
              ],
              text=True,
          )
          gradle = subprocess.check_output(
              ["git", "show", "origin/main:app/build.gradle.kts"],
              text=True,
          )
          
          checks = {
              "full control helper":
                  "private fun TvPlayerControlButton(" in player,
              "all core controls":
                  all(
                      token in player
                      for token in (
                          'id = "previous"',
                          'id = "rewind"',
                          'id = "play"',
                          'id = "forward"',
                          'id = "next"',
                          'id = "audio"',
                          'id = "subtitles"',
                          'id = "sources"',
                      )
                  ),
              "Down enters bar":
                  "requestControlFocus()" in player,
              "Play gets initial bar focus":
                  "playControlRequester.requestFocus()" in player,
              "bar prevents auto hide":
                  "focusedControlId == null" in player,
              "track focus returns":
                  "audioControlRequester.requestFocus()" in player and
                  "subtitleControlRequester.requestFocus()" in player,
              "auto-next retained":
                  "autoNextCountdown" in player and
                  "Key.MediaPrevious" in player and
                  "Key.MediaNext" in player,
              "subtitle/audio retained":
                  "setSubtitleConfigurations(subtitleConfigurations)" in player and
                  "setPreferredTextLanguages" in player,
              "headers retained":
                  "setDefaultRequestProperties(stream.headers)" in player,
              "details path retained":
                  "StreamSourceAggregator(context)" in details and
                  "SubtitleSourceAggregator(context)" in details and
                  "TvPlayerScreen(" in details,
              "version":
                  f'versionName = "{target}"' in gradle,
          }
          
          failed = [name for name, ok in checks.items() if not ok]
          if failed:
              raise SystemExit(
                  "REMOTE V2.1-C VERIFY FAILED: " + ", ".join(failed)
              )
          
          for name in checks:
              print("PASS:", name)
          PY

      - name: Dispatch signed updater build
        shell: bash
        env:
          GH_TOKEN: ${{ github.token }}
        run: |
          set -euo pipefail

          HEAD_SHA="$(git rev-parse origin/main)"
          echo "HEAD_SHA=$HEAD_SHA" >> "$GITHUB_ENV"

          gh workflow run build.yml             --repo "$GITHUB_REPOSITORY"             --ref main             -f publish_release=true

          sleep 8

          RUN_ID=""
          for attempt in $(seq 1 24); do
            RUN_ID="$(
              gh run list                 --repo "$GITHUB_REPOSITORY"                 --workflow build.yml                 --branch main                 --event workflow_dispatch                 --limit 20                 --json databaseId,headSha                 --jq ".[] | select(.headSha == \"$HEAD_SHA\") | .databaseId"                 | head -n1
            )"
            if [[ -n "$RUN_ID" ]]; then
              break
            fi
            sleep 5
          done

          test -n "$RUN_ID"
          echo "SIGNED_RUN_ID=$RUN_ID" >> "$GITHUB_ENV"
          echo "signed_run_id=$RUN_ID"             | tee "$RUNNER_TEMP/tv-v21c/signed-run.txt"

      - name: Wait signed updater build
        shell: bash
        env:
          GH_TOKEN: ${{ github.token }}
        run: |
          set -euo pipefail
          gh run watch "$SIGNED_RUN_ID"             --repo "$GITHUB_REPOSITORY"             --exit-status             2>&1 | tee "$RUNNER_TEMP/tv-v21c/signed-build-watch.log"

      - name: Verify published V2.1-C
        shell: bash
        run: |
          set -euo pipefail

          MANIFEST="$RUNNER_TEMP/tv-v21c/update.json"

          for attempt in $(seq 1 24); do
            curl               --fail               --location               --silent               --show-error               --header 'Cache-Control: no-cache'               "https://github.com/$GITHUB_REPOSITORY/releases/latest/download/update.json?ts=$(date +%s)"               --output "$MANIFEST" || true

            if grep -q '0.27.2-tv-v2.1c-controlbar' "$MANIFEST" 2>/dev/null; then
              break
            fi
            sleep 5
          done

          test -s "$MANIFEST"
          grep -q '0.27.2-tv-v2.1c-controlbar' "$MANIFEST"
          cat "$MANIFEST"             | tee "$RUNNER_TEMP/tv-v21c/published-update.json"

      - name: Compact failure summary
        if: failure()
        shell: bash
        run: |
          set +e
          DIR="$RUNNER_TEMP/tv-v21c"

          echo "========== Nustrim TV V2.1-C P1 =========="
          echo "RESULT: FAILED"

          for f in             preflight.txt             changed-files.txt             remote-main.txt             signed-run.txt             published-update.json; do
            if [[ -f "$DIR/$f" ]]; then
              echo
              echo "===== $f ====="
              cat "$DIR/$f" || true
            fi
          done

          for f in             compile.log             tests.log             lint-release.log             assemble.log             push.log             signed-build-watch.log; do
            if [[ -f "$DIR/$f" ]]; then
              echo
              echo "===== $f ====="
              tail -n 340 "$DIR/$f" || true
            fi
          done

      - name: Upload diagnose
        if: always()
        uses: actions/upload-artifact@v7
        with:
          name: nustrim-tv-v2-1c-full-player-controlbar-p1-diagnose
          path: ${{ runner.temp }}/tv-v21c
          if-no-files-found: ignore
          retention-days: 7
